             CMD        PROMPT('Duplicate Message Description')

             PARM       KWD(RANGE) +
                        TYPE(QMSGR) +
                        SNGVAL( +
                          (*ALL )) +
                        PROMPT('Range of message identifiers')

             PARM       KWD(FROMMSGF)                          +
                        TYPE(QUAL1)                            +
                        MIN(0)                                 +
                        PROMPT('From message file')

             PARM       KWD(TOMSGID)                           +
                        TYPE(*CHAR)                            +
                        LEN(7)                                 +
                        EXPR(*YES)                             +
                        DFT(*FROMID)                           +
                        PROMPT('To message description')

             PARM       KWD(TOMSGF)                            +
                        TYPE(QUAL2)                            +
                        PROMPT('To message file')

             PARM       KWD(REPLACE)                           +
                        TYPE(*CHAR)                            +
                        LEN(1)                                 +
                        EXPR(*YES)                             +
                        DFT(*NO)                               +
                        RSTD(*YES)                             +
                        SPCVAL((*YES Y)                        +
                               (*NO  N))                       +
                        PROMPT('Replace message description')

             PARM       KWD(MSGFLNG   ) TYPE(*CHAR)        +
                          LEN(10)                          +
                          CONSTANT(DUPMSGDE )

QMSGR:       ELEM       TYPE(*NAME) +
                        LEN(7) +
                        DFT(*FIRST) +
                        SPCVAL( +
                          (*FIRST *FIRST )) +
                        FULL(*YES) +
                        EXPR(*YES) +
                        PROMPT('Lower value')
             ELEM       TYPE(*NAME) +
                        LEN(7) +
                        DFT(*ONLY) +
                        SPCVAL( +
                          (*ONLY *ONLY  ) +
                          (*LAST *LAST  )) +
                        FULL(*YES) +
                        EXPR(*YES) +
                        PROMPT('Upper value')

QUAL1:       QUAL       TYPE(*NAME) LEN(10)                    +
                        DFT(QCPFMSG)
             QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*LIBL)                             +
                        SPCVAL((*LIBL   )                      +
                               (*CURLIB ))                     +
                        PROMPT('Library')

QUAL2:       QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*FROMMSGF)                         +
                        SPCVAL(*FROMMSGF)
             QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*LIBL)                             +
                        SPCVAL((*LIBL   )                      +
                               (*CURLIB ))                     +
                        PROMPT('Library')

